import { NextResponse } from "next/server";
import { getAuthedContext } from "@/lib/backend";
export async function POST(request:Request,{params}:{params:Promise<{id:string}>}){const {supabase,user,organizationId}=await getAuthedContext();if(!supabase||!user||!organizationId)return NextResponse.json({error:"Authentication required"},{status:401});const {id}=await params;const f=await request.formData();const file=f.get("file");if(!(file instanceof File))return NextResponse.json({error:"File required"},{status:400});if(file.size>10*1024*1024)return NextResponse.json({error:"File exceeds 10 MB"},{status:400});const safe=file.name.replace(/[^a-zA-Z0-9._-]/g,"-");const path=`${organizationId}/${id}/${crypto.randomUUID()}-${safe}`;const {error:uploadError}=await supabase.storage.from("vendor-private").upload(path,file,{contentType:file.type,upsert:false});if(uploadError)return NextResponse.json({error:uploadError.message},{status:400});const {data,error}=await supabase.from("vendor_documents").insert({organization_id:organizationId,vendor_id:id,credential_id:f.get("credentialId")||null,document_type:f.get("documentType")||"other",storage_path:path,file_name:file.name,mime_type:file.type,contains_sensitive_tax_data:f.get("documentType")==="w9",uploaded_by:user.id}).select().single();if(error){await supabase.storage.from("vendor-private").remove([path]);return NextResponse.json({error:error.message},{status:400});}return NextResponse.json({document:data},{status:201});}
export async function GET(request:Request,{params}:{params:Promise<{id:string}>}){const {supabase,user,organizationId}=await getAuthedContext();if(!supabase||!user||!organizationId)return NextResponse.json({error:"Authentication required"},{status:401});const {id}=await params;const documentId=new URL(request.url).searchParams.get("documentId");const {data:doc}=await supabase.from("vendor_documents").select("storage_path").eq("id",documentId).eq("vendor_id",id).eq("organization_id",organizationId).single();if(!doc)return NextResponse.json({error:"Document not found"},{status:404});const {data,error}=await supabase.storage.from("vendor-private").createSignedUrl(doc.storage_path,60,{download:true});return error?NextResponse.json({error:error.message},{status:400}):NextResponse.json({url:data.signedUrl});}
